WITH pr(k, m) AS ( SELECT * FROM unnest(CAST($1 AS uuid[]), CAST($2 AS uuid[]))), keys(k) AS (SELECT * FROM unnest(CAST($3 AS uuid[]))), fp AS MATERIALIZED ( SELECT e3.src AS post, e3.dst AS m FROM anchors e3 WHERE e3.kind = 'EdgeAnchor' AND e3.arch_type = 'HasCreator' AND e3.dst_type = 'Person' AND e3.src_type = 'Post' AND e3.dst = ANY(CAST($4 AS uuid[]))), fc AS MATERIALIZED ( SELECT e2.src AS k, fp.m AS m FROM fp JOIN anchors e2 ON e2.kind = 'EdgeAnchor' AND e2.arch_type = 'ContainerOf' AND e2.dst_type = 'Post' AND e2.dst = fp.post), cnt AS ( SELECT pr.k AS k, count(*) AS c FROM pr JOIN fc ON fc.k = pr.k AND fc.m = pr.m GROUP BY pr.k) SELECT keys.k, COALESCE(cnt.c, 0) AS hc FROM keys LEFT JOIN cnt ON cnt.k = keys.k JOIN g_n_forum_d2a57d m ON m.id = keys.k ORDER BY hc DESC, CASE WHEN jsonb_typeof(m.f_forum_id) = 'number' THEN (m.f_forum_id)::numeric END ASC NULLS LAST, (m.f_forum_id #>> '{}') COLLATE "C" ASC LIMIT $5